/* THE TWO FACES THE WHOLE PIANO PAGE IS WRITTEN IN. Chewy writes the English, ChillRound M the Chinese
   (user 2026-10-31: page UI everywhere, not just the sheet). They live in their own file because a font is
   bytes, not drawing code: base64 woff2 in the page, so OUT.html stays one self-contained file (build.py
   inlines this <script> like tunes.js). BOTH ARE SUBSETS — ChillRound M is 6.2 MB whole, cut down to the
   tune names plus every quoted UI literal in piano.html/core.js/OUT.html plus printable ASCII. Adding a
   tune or page copy with characters outside that set degrades gracefully to the system CJK face; re-run
   scripts/subset-fonts.sh in the colorfigures skill to keep the look. */
(function(){
  const s = document.createElement('style');
  s.textContent =
    "@font-face{font-family:'SheetHand';font-style:normal;font-weight:400;src:url(data:font/woff2;base64,) format('woff2')}" +
    "@font-face{font-family:'SheetRound';font-style:normal;font-weight:400;src:url(data:font/woff2;base64,) format('woff2')}";
  document.head.appendChild(s);
})();
